const names = ['fetch','URL','URLSearchParams','AbortController','structuredClone','Blob','FormData','TextEncoder','atob','btoa','Buffer','setTimeout','process','crypto','require'];
const out = {};
for (const n of names) { try { out[n] = eval('typeof ' + n); } catch (e) { out[n] = 'error: ' + e.message; } }
out['this.helpers.httpRequest'] = typeof this.helpers?.httpRequest;
for (const m of ['crypto','fs','moment','lodash']) { try { require(m); out['require(' + m + ')'] = 'ok'; } catch (e) { out['require(' + m + ')'] = e.message; } }
return [{ json: out }];
